CREATE SEQUENCE IF NOT EXISTS public.logistics_exception_seq;
GRANT USAGE, SELECT ON SEQUENCE public.logistics_exception_seq TO authenticated, service_role;
DO $$ BEGIN CREATE TYPE public.commercial_document_status AS ENUM ('draft', 'pending_approval', 'approved', 'sent', 'accepted', 'rejected', 'expired', 'cancelled', 'issued', 'partially_paid', 'paid', 'tax_validation', 'etims_pending', 'etims_accepted', 'etims_exception', 'delivered', 'correction_required', 'superseded', 'voided'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.commercial_document_type AS ENUM ('quotation', 'proforma', 'tax_invoice', 'payment_receipt'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.corporate_approval_status AS ENUM ('pending','approved','rejected','expired','cancelled'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.corporate_employee_role AS ENUM ('corporate_admin','corporate_manager','corporate_employee'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.corporate_employee_status AS ENUM ('invited','active','suspended','removed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.corporate_policy_scope AS ENUM ('corporate','department','employee'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.dispatch_candidate_status AS ENUM ('SCORED','OFFERED','ACCEPTED','REJECTED','TIMEOUT','SKIPPED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.dispatch_status AS ENUM ('PENDING','MATCHING','OFFERED','ACCEPTED','REJECTED','EXPIRED','ASSIGNED','CANCELLED','COMPLETED','FAILED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.ride_receivable_state AS ENUM ('OPEN','INVOICED','SETTLED','WRITTEN_OFF','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE public.surge_approval_status AS ENUM ('PENDING','APPROVED','REJECTED','EXPIRED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS public.air_pricing_settings ( id int PRIMARY KEY DEFAULT 1 CHECK (id = 1), fx_kes_per_usd numeric NOT NULL DEFAULT 129, season_multipliers jsonb NOT NULL DEFAULT '{"1":1.1,"2":1,"3":1,"4":0.88,"5":0.88,"6":1,"7":1.15,"8":1.15,"9":1.12,"10":1.05,"11":0.95,"12":1.2}', weekend_multiplier numeric NOT NULL DEFAULT 1.05, urgent_hours int NOT NULL DEFAULT 48, urgent_multiplier numeric NOT NULL DEFAULT 1.12, early_days int NOT NULL DEFAULT 30, early_multiplier numeric NOT NULL DEFAULT 0.95, one_way_return_pct numeric NOT NULL DEFAULT 0.5, taxi_hours numeric NOT NULL DEFAULT 0.25, yalla_fee_pct numeric NOT NULL DEFAULT 0.08, updated_at timestamptz NOT NULL DEFAULT now(), updated_by uuid );
CREATE TABLE IF NOT EXISTS public.alert_dispatch_dlq ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), event_id UUID, rule_id TEXT, rule_name TEXT, severity TEXT, channel TEXT NOT NULL, payload JSONB NOT NULL, last_error TEXT, attempt_count INTEGER NOT NULL DEFAULT 0, next_retry_at TIMESTAMPTZ NOT NULL DEFAULT now(), resolved_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.alert_escalation_routes ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, severity TEXT NOT NULL CHECK (severity IN ('info','warning','critical')), match_rule_id TEXT, match_metric_key TEXT, email_recipients TEXT[] NOT NULL DEFAULT '{}', slack_webhook_urls TEXT[] NOT NULL DEFAULT '{}', target_roles TEXT[] NOT NULL DEFAULT '{}', priority INTEGER NOT NULL DEFAULT 100, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_by UUID REFERENCES auth.users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ap360_engines ( code text PRIMARY KEY, label text NOT NULL, summary text NOT NULL, parameter_keys text[] NOT NULL, required_keys text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ap360_families ( code text PRIMARY KEY, label text NOT NULL, sort_order integer NOT NULL DEFAULT 100, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.approval_routes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workflow_id uuid NOT NULL REFERENCES public.approval_workflows(id) ON DELETE CASCADE, step_no int NOT NULL, approver_user_id uuid, approver_role app_role, required boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (workflow_id, step_no) );
CREATE TABLE IF NOT EXISTS public.asset_pricing_versions ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, code text NOT NULL DEFAULT 'YALLA-ASSET-BANDS', version integer NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','under_review','approved','published','superseded','archived')), currency text NOT NULL DEFAULT 'KES', effective_from timestamptz NOT NULL DEFAULT now(), note text NOT NULL DEFAULT '', created_by uuid, approved_by uuid, approved_at timestamptz, published_by uuid, published_at timestamptz, superseded_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (code, version) );
CREATE TABLE IF NOT EXISTS public.charter_pricing_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_type text NOT NULL CHECK (entity_type IN ('quote','booking','inventory')), entity_id uuid, reference text, actor_id uuid, actor_email text, action text NOT NULL, category_slug text, asset_name text, previous_settings jsonb NOT NULL DEFAULT '{}'::jsonb, cost_settings jsonb NOT NULL DEFAULT '{}'::jsonb, changed_fields jsonb NOT NULL DEFAULT '[]'::jsonb, breakdown jsonb NOT NULL DEFAULT '{}'::jsonb, currency text, total numeric, evidence_hash text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.charter_pricing_config ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, version INTEGER NOT NULL, effective_at TIMESTAMPTZ NOT NULL DEFAULT now(), actor_id UUID, actor_email TEXT, note TEXT NOT NULL DEFAULT '', config JSONB NOT NULL DEFAULT '{}'::jsonb, changes JSONB NOT NULL DEFAULT '[]'::jsonb, evidence_hash TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (version) );
CREATE TABLE IF NOT EXISTS public.commercial_documents ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_number text NOT NULL UNIQUE, document_type public.commercial_document_type NOT NULL, transaction_id uuid NOT NULL REFERENCES public.commercial_transactions(id), transaction_ref text NOT NULL, version integer NOT NULL DEFAULT 1, supersedes_id uuid REFERENCES public.commercial_documents(id), source_document_id uuid REFERENCES public.commercial_documents(id), source_type text, source_ref text, source_version integer, source_total_cents bigint, corporate_id uuid REFERENCES public.corporate_accounts(id), customer_user_id uuid, currency text NOT NULL DEFAULT 'KES', subtotal_cents bigint NOT NULL DEFAULT 0 CHECK (subtotal_cents >= 0), tax_cents bigint NOT NULL DEFAULT 0 CHECK (tax_cents >= 0), total_cents bigint NOT NULL DEFAULT 0 CHECK (total_cents >= 0), status public.commercial_document_status NOT NULL DEFAULT 'draft', document_hash text, hash_algorithm text NOT NULL DEFAULT 'sha256', storage_ref text, etims_invoice_id uuid REFERENCES public.etims_invoices(id), payment_ref text, recipient_email text, idempotency_key text, risk_level text NOT NULL DEFAULT 'LOW' CHECK (risk_level IN ('LOW','MEDIUM','HIGH','CRITICAL')), approved_by uuid, approved_at timestamptz, issued_at timestamptz, sent_at timestamptz, delivered_at timestamptz, voided_at timestamptz, voided_reason text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (transaction_id, document_type, version) );
CREATE TABLE IF NOT EXISTS public.commercial_pricing_requests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES public.crm_accounts(id) ON DELETE CASCADE, opportunity_id uuid REFERENCES public.commercial_opportunities(id) ON DELETE SET NULL, rate_card_id uuid REFERENCES public.commercial_rate_cards(id) ON DELETE SET NULL, requested_by_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, service_code text NOT NULL, scope_label text, category_code text, requirement text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','withdrawn')), decided_by uuid, decided_at timestamptz, decision_note text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.commercial_quotations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), quote_number text NOT NULL UNIQUE, account_id uuid NOT NULL REFERENCES public.crm_accounts(id) ON DELETE CASCADE, opportunity_id uuid REFERENCES public.commercial_opportunities(id) ON DELETE SET NULL, contract_instance_id uuid REFERENCES public.commercial_contract_instances(id) ON DELETE SET NULL, rate_card_id uuid NOT NULL REFERENCES public.commercial_rate_cards(id) ON DELETE RESTRICT, rate_card_version text NOT NULL, owner_staff_id uuid REFERENCES public.staff_members(id) ON DELETE SET NULL, currency text NOT NULL DEFAULT 'KES', total_amount numeric(14,2) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'draft' CHECK (status IN ( 'draft','submitted','approved','shared','accepted','declined','expired','superseded')), approval_status text NOT NULL DEFAULT 'not_required' CHECK (approval_status IN ( 'not_required','pending','approved','rejected')), valid_until date, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.corporate_departments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, name text NOT NULL, code text, cost_center text, monthly_budget_cents bigint, manager_user_id uuid, active boolean NOT NULL DEFAULT true, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (corporate_id, name) );
CREATE TABLE IF NOT EXISTS public.country_pricing_floors ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), country_code TEXT NOT NULL, city TEXT, ride_type TEXT NOT NULL, currency TEXT NOT NULL, minimum_fare NUMERIC(10,2) NOT NULL, minimum_per_km NUMERIC(10,2), minimum_per_minute NUMERIC(10,2), source_ref TEXT, effective_from DATE, is_active BOOLEAN NOT NULL DEFAULT true, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.delivery_eta_predictions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), package_id uuid REFERENCES public.packages(id) ON DELETE CASCADE, job_id uuid REFERENCES public.delivery_dispatch_jobs(id) ON DELETE CASCADE, predicted_eta timestamptz NOT NULL, confidence numeric(5,4), model_version text, features jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.delivery_route_segments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES public.delivery_dispatch_jobs(id) ON DELETE CASCADE, segment_index integer NOT NULL, start_lat numeric(10,7), start_lng numeric(10,7), end_lat numeric(10,7), end_lng numeric(10,7), distance_m integer, duration_s integer, polyline text, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.dispatch_acceptance_stats ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, driver_id UUID NOT NULL, window_size INTEGER NOT NULL DEFAULT 50, offers_received INTEGER NOT NULL DEFAULT 0, offers_accepted INTEGER NOT NULL DEFAULT 0, offers_rejected INTEGER NOT NULL DEFAULT 0, offers_expired INTEGER NOT NULL DEFAULT 0, acceptance_rate NUMERIC(5,4) NOT NULL DEFAULT 0, completion_rate NUMERIC(5,4) NOT NULL DEFAULT 0, computed_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT uq_acceptance_driver UNIQUE (driver_id, window_size) );
CREATE TABLE IF NOT EXISTS public.dispatch_approval_audit ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), zone_id uuid NOT NULL, actor_user_id uuid, actor_email text, actor_role text, action text NOT NULL, previous_state public.surge_approval_status, new_state public.surge_approval_status, reason text, note text, ip_address text, user_agent text, request_id text, correlation_id text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.dispatch_approval_rate_limits ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id uuid NOT NULL, window_start timestamptz NOT NULL, attempt_count integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(actor_user_id, window_start) );
CREATE TABLE IF NOT EXISTS public.dispatch_demand_signals ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, cell_key TEXT NOT NULL, window_start TIMESTAMPTZ NOT NULL, window_end TIMESTAMPTZ NOT NULL, request_count INTEGER NOT NULL DEFAULT 0, unfulfilled_count INTEGER NOT NULL DEFAULT 0, avg_eta_seconds INTEGER, surge_recommendation NUMERIC(5,2), created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.dispatch_performance_metrics (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), metric_date date NOT NULL, region_code text, total_requests int NOT NULL DEFAULT 0, matched_requests int NOT NULL DEFAULT 0, failed_requests int NOT NULL DEFAULT 0, avg_match_seconds numeric(8,2), avg_eta_seconds numeric(8,2), acceptance_rate numeric(5,4), cancellation_rate numeric(5,4), surge_avg numeric(5,2), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (metric_date, region_code));
CREATE TABLE IF NOT EXISTS public.dispatch_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rider_id uuid, corporate_id uuid REFERENCES public.corporate_accounts(id) ON DELETE SET NULL, pickup_lat double precision NOT NULL, pickup_lng double precision NOT NULL, pickup_address text, dropoff_lat double precision, dropoff_lng double precision, dropoff_address text, vehicle_category text, requested_at timestamptz NOT NULL DEFAULT now(), scheduled_for timestamptz, status public.dispatch_status NOT NULL DEFAULT 'PENDING', surge_multiplier numeric(5,2) NOT NULL DEFAULT 1.0, estimated_fare_cents bigint, currency text NOT NULL DEFAULT 'KES', assigned_driver_id uuid, assigned_at timestamptz, completed_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.dispatch_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rule_code text UNIQUE NOT NULL, name text NOT NULL, description text, active boolean NOT NULL DEFAULT true, current_version int NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.dispatch_sim_scenarios ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, name TEXT NOT NULL, description TEXT, rule_version TEXT, driver_distribution JSONB NOT NULL DEFAULT '{}'::jsonb, rider_distribution JSONB NOT NULL DEFAULT '{}'::jsonb, request_rate_per_min INTEGER NOT NULL DEFAULT 10, duration_minutes INTEGER NOT NULL DEFAULT 15, driver_acceptance_rate NUMERIC(4,3) NOT NULL DEFAULT 0.8, created_by UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.dispatch_supply_cells ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, cell_key TEXT NOT NULL UNIQUE, center_lat DOUBLE PRECISION NOT NULL, center_lng DOUBLE PRECISION NOT NULL, resolution SMALLINT NOT NULL DEFAULT 7, online_drivers INTEGER NOT NULL DEFAULT 0, available_drivers INTEGER NOT NULL DEFAULT 0, demand_1m INTEGER NOT NULL DEFAULT 0, demand_5m INTEGER NOT NULL DEFAULT 0, demand_15m INTEGER NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.dispatch_surge_zone_versions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), zone_id uuid NOT NULL, version integer NOT NULL, approval_status public.surge_approval_status NOT NULL, multiplier numeric NOT NULL, priority integer NOT NULL, active boolean NOT NULL, first_approver_id uuid, approved_by uuid, rejected_by uuid, requested_by uuid, snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, changed_by uuid, change_reason text, request_id text, correlation_id text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(zone_id, version) );
CREATE TABLE IF NOT EXISTS public.dispatch_surge_zones ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, cell_key TEXT NOT NULL, multiplier NUMERIC(5,2) NOT NULL DEFAULT 1.0, reason TEXT, source TEXT NOT NULL DEFAULT 'auto', valid_from TIMESTAMPTZ NOT NULL DEFAULT now(), valid_to TIMESTAMPTZ, active BOOLEAN NOT NULL DEFAULT true, created_by UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT chk_surge_source CHECK (source IN ('auto','manual','scheduled')), CONSTRAINT chk_surge_multiplier CHECK (multiplier >= 1.0 AND multiplier <= 10.0) );
CREATE TABLE IF NOT EXISTS public.document_metadata (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL, document_table text NOT NULL, field_name text NOT NULL, field_value text, confidence numeric(5,4), source text NOT NULL DEFAULT 'OCR', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.email_event_dispatch ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, idempotency_key TEXT NOT NULL UNIQUE, event_key TEXT, recipient_email TEXT NOT NULL, message_id TEXT NOT NULL, correlation_id TEXT, replay_count INTEGER NOT NULL DEFAULT 0, last_replay_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.fact_trips (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trip_id uuid NOT NULL, driver_id uuid, rider_id uuid, corporate_id uuid, country_code text, trip_date date NOT NULL, distance_km numeric(8,2), duration_s int, fare_cents bigint, commission_cents bigint, surge_multiplier numeric(5,2), payment_method text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.fin_bank_receipts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), channel_id uuid NOT NULL REFERENCES public.yalla_payment_channels(id), external_reference text NOT NULL, payer_reference text, amount_cents bigint NOT NULL CHECK (amount_cents > 0), currency text NOT NULL DEFAULT 'KES', paid_at timestamptz NOT NULL, statement_reference text, evidence_note text, recorded_by uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (channel_id, external_reference) );
CREATE TABLE IF NOT EXISTS public.freight_price_lineage ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requirement_id uuid NOT NULL REFERENCES public.freight_requirements(id) ON DELETE CASCADE, rfq_id uuid REFERENCES public.freight_rfqs(id) ON DELETE SET NULL, quotation_id uuid REFERENCES public.carrier_quotations(id) ON DELETE SET NULL, award_id uuid REFERENCES public.freight_awards(id) ON DELETE SET NULL, booking_id uuid REFERENCES public.freight_bookings(id) ON DELETE SET NULL, carrier_id uuid REFERENCES public.carrier_profiles(id) ON DELETE SET NULL, stage text NOT NULL CHECK (stage IN ('REQUESTED','QUOTED','ACCEPTED','ACTUAL','ADJUSTED','INVOICED','SETTLED')), amount numeric(14,2) NOT NULL, currency text NOT NULL DEFAULT 'KES', breakdown jsonb NOT NULL DEFAULT '{}'::jsonb, variance_vs_accepted numeric(14,2), invoice_reference text, settlement_reference text, recorded_by uuid, recorded_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.freight_repeat_routes ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route_code text NOT NULL UNIQUE, route_name text NOT NULL, status text NOT NULL DEFAULT 'DRAFT', service_type text NOT NULL DEFAULT 'DEDICATED_FREIGHT', dedicated_customer_id uuid, origin_label text NOT NULL, origin_lat numeric(9,6), origin_lng numeric(9,6), origin_hub_id uuid REFERENCES public.logistics_hubs(id), destination_label text NOT NULL, destination_lat numeric(9,6), destination_lng numeric(9,6), destination_hub_id uuid REFERENCES public.logistics_hubs(id), distance_km numeric(10,2), vehicle_class text NOT NULL, committed_capacity_kg numeric(12,2) NOT NULL, committed_volume_cbm numeric(12,3) NOT NULL DEFAULT 0, weekday_mask integer[] NOT NULL, departure_time time NOT NULL, arrival_target_time time, booking_cutoff_minutes integer NOT NULL DEFAULT 60, effective_from date NOT NULL, effective_until date, generation_horizon_days integer NOT NULL DEFAULT 30, allow_overbooking boolean NOT NULL DEFAULT false, overbooking_tolerance_pct numeric(5,2) NOT NULL DEFAULT 0, vehicle_assignment_mode text NOT NULL DEFAULT 'DYNAMIC', driver_assignment_mode text NOT NULL DEFAULT 'DYNAMIC', dedicated_vehicle_id uuid REFERENCES public.vehicles(id), dedicated_driver_id uuid REFERENCES public.drivers(id), rate_plan_code text, currency text NOT NULL DEFAULT 'KES', notes text, approved_by uuid, approved_at timestamptz, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rr_status CHECK (status = ANY (ARRAY['DRAFT','PENDING_APPROVAL','APPROVED','ACTIVE','SUSPENDED','COMPLETED','RETIRED'])), CONSTRAINT rr_class CHECK (vehicle_class = ANY (ARRAY['TRUCK_3T','TRUCK_7T','TRUCK_14T','TRUCK_28T'])), CONSTRAINT rr_capacity CHECK (committed_capacity_kg > 0), CONSTRAINT rr_volume CHECK (committed_volume_cbm >= 0), CONSTRAINT rr_cutoff CHECK (booking_cutoff_minutes >= 0 AND booking_cutoff_minutes <= 1440), CONSTRAINT rr_horizon CHECK (generation_horizon_days BETWEEN 1 AND 120), CONSTRAINT rr_weekdays CHECK (cardinality(weekday_mask) > 0), CONSTRAINT rr_overbook CHECK (overbooking_tolerance_pct >= 0 AND overbooking_tolerance_pct <= 25 AND (allow_overbooking OR overbooking_tolerance_pct = 0)), CONSTRAINT rr_assign_mode CHECK (vehicle_assignment_mode = ANY (ARRAY['DYNAMIC','DEDICATED']) AND driver_assignment_mode = ANY (ARRAY['DYNAMIC','DEDICATED'])), CONSTRAINT rr_dates CHECK (effective_until IS NULL OR effective_until >= effective_from) );
CREATE TABLE IF NOT EXISTS public.logistics_delivery_attempts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), package_id uuid NOT NULL REFERENCES public.packages(id) ON DELETE CASCADE, order_id uuid, attempt_number integer NOT NULL, outcome text NOT NULL CHECK (outcome IN ('delivered','failed','refused','rescheduled','returned')), reason_code text, narrative text, driver_id uuid, actor_id uuid, location_lat numeric, location_lng numeric, recipient_name text, pod_id uuid, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, idempotency_key text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (idempotency_key), UNIQUE (package_id, attempt_number) );
CREATE TABLE IF NOT EXISTS public.logistics_dispatch_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dispatch_request_id uuid NOT NULL REFERENCES public.logistics_dispatch_requests(id) ON DELETE CASCADE, event_type text NOT NULL, previous_status text, new_status text, actor_id uuid, actor_role text, reason text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, occurred_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_hub_zones ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), hub_id uuid NOT NULL REFERENCES public.logistics_hubs(id) ON DELETE CASCADE, code text NOT NULL, name text NOT NULL, zone_type text NOT NULL CHECK (zone_type = ANY (ARRAY['RECEIVING','SORTING','STAGING','STORAGE','PICKING','PACKING','DISPATCH','RETURNS','QUARANTINE','COLD_CHAIN'])), status text NOT NULL DEFAULT 'ACTIVE' CHECK (status = ANY (ARRAY['ACTIVE','BLOCKED','MAINTENANCE','QUARANTINED'])), temperature_min_c numeric, temperature_max_c numeric, notes text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (hub_id, code) );
CREATE TABLE IF NOT EXISTS public.logistics_match_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dispatch_request_id uuid NOT NULL REFERENCES public.logistics_dispatch_requests(id) ON DELETE CASCADE, mode text NOT NULL DEFAULT 'COMMIT', weights_version integer, candidate_count integer NOT NULL DEFAULT 0, eligible_count integer NOT NULL DEFAULT 0, rejected_count integer NOT NULL DEFAULT 0, selected_vehicle_id uuid, selected_driver_id uuid, selected_score numeric(6,2), selection_reason text, outcome text NOT NULL, matching_duration_ms integer, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT match_run_mode CHECK (mode = ANY (ARRAY['COMMIT','SIMULATE'])), CONSTRAINT match_run_outcome CHECK (outcome = ANY (ARRAY['MATCHED','NO_CAPACITY','RESERVATION_CONFLICT','SIMULATED','ERROR'])) );
CREATE TABLE IF NOT EXISTS public.logistics_match_weights ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version integer NOT NULL UNIQUE, active boolean NOT NULL DEFAULT false, w_capacity numeric(5,2) NOT NULL, w_class numeric(5,2) NOT NULL, w_driver numeric(5,2) NOT NULL, w_proximity numeric(5,2) NOT NULL, w_route numeric(5,2) NOT NULL, w_availability numeric(5,2) NOT NULL, w_compliance numeric(5,2) NOT NULL, w_schedule numeric(5,2) NOT NULL, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_route_optimization_runs ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route_id uuid NOT NULL REFERENCES public.logistics_routes(id) ON DELETE CASCADE, route_version_id uuid REFERENCES public.logistics_route_versions(id) ON DELETE SET NULL, result_version_id uuid REFERENCES public.logistics_route_versions(id) ON DELETE SET NULL, provider_key text NOT NULL DEFAULT 'manual', status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','succeeded','failed','skipped')), request jsonb NOT NULL DEFAULT '{}'::jsonb, response jsonb, error text, requested_by uuid, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz );
CREATE TABLE IF NOT EXISTS public.marketplace_dispatch_zones ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, zone_type TEXT NOT NULL DEFAULT 'standard', country_code TEXT NOT NULL DEFAULT 'KE', city TEXT, polygon JSONB, hex_ids UUID[], priority INTEGER NOT NULL DEFAULT 100, is_active BOOLEAN NOT NULL DEFAULT true, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.marketplace_hex_cells ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), h3_index TEXT NOT NULL UNIQUE, resolution SMALLINT NOT NULL DEFAULT 8, country_code TEXT NOT NULL DEFAULT 'KE', region TEXT, city TEXT, center_lat NUMERIC(10,7) NOT NULL, center_lng NUMERIC(10,7) NOT NULL, polygon JSONB, area_km2 NUMERIC(10,4), is_active BOOLEAN NOT NULL DEFAULT true, is_service_area BOOLEAN NOT NULL DEFAULT true, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.marketplace_pricing_rules ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, ride_type TEXT NOT NULL, country_code TEXT NOT NULL DEFAULT 'KE', city TEXT, currency TEXT NOT NULL DEFAULT 'KES', base_fare NUMERIC(10,2) NOT NULL, per_km NUMERIC(10,2) NOT NULL, per_minute NUMERIC(10,2) NOT NULL, minimum_fare NUMERIC(10,2) NOT NULL, booking_fee NUMERIC(10,2) NOT NULL DEFAULT 0, cancellation_fee NUMERIC(10,2) NOT NULL DEFAULT 0, surge_enabled BOOLEAN NOT NULL DEFAULT true, max_surge_multiplier NUMERIC(4,2) NOT NULL DEFAULT 3.00, effective_from TIMESTAMPTZ NOT NULL DEFAULT now(), effective_until TIMESTAMPTZ, is_active BOOLEAN NOT NULL DEFAULT true, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.partner_lifecycle_dispatch_windows ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id text NOT NULL UNIQUE, window_seconds integer NOT NULL DEFAULT 120, window_started_at timestamptz NOT NULL DEFAULT now(), last_signal_id uuid, last_work_item_id uuid, last_notification_id uuid, batched_count integer NOT NULL DEFAULT 0, batched_stages text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.pricing360_feature_flags ( key text PRIMARY KEY, enabled boolean NOT NULL DEFAULT true, note text NOT NULL DEFAULT '', updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.pricing360_role_grants ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), role text NOT NULL, permission text NOT NULL, allowed boolean NOT NULL DEFAULT false, reason text NOT NULL DEFAULT '', updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (role, permission) );
CREATE TABLE IF NOT EXISTS public.pricing_audit_events ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, actor_id uuid, actor_email text, action text NOT NULL, entity text NOT NULL, entity_id uuid, previous_value jsonb, new_value jsonb, reason text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.pricing_guardrails ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, label text NOT NULL, direction text NOT NULL CHECK (direction IN ('discount','premium')), variance_from numeric(6,2) NOT NULL, variance_to numeric(6,2), action text NOT NULL CHECK (action IN ('none','notify','approve')), required_role text, scope jsonb NOT NULL DEFAULT '{}'::jsonb, active boolean NOT NULL DEFAULT true, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.pricing_rule_sets ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, code text NOT NULL, name text NOT NULL, domain text NOT NULL CHECK (domain = ANY (ARRAY['ride_hailing','corporate_charter','delivery','logistics','rentals','leasing','all'])), version text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK (status = ANY (ARRAY['draft','under_review','approved','scheduled','published','superseded','archived'])), currency text NOT NULL DEFAULT 'KES', effective_from timestamptz NOT NULL DEFAULT now(), effective_until timestamptz, note text NOT NULL DEFAULT '', created_by uuid, approved_by uuid, approved_at timestamptz, published_by uuid, published_at timestamptz, superseded_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (code, version) );
CREATE TABLE IF NOT EXISTS public.pricing_service_engines ( code text PRIMARY KEY, name text NOT NULL, quote_kind text NOT NULL CHECK (quote_kind IN ('instant','rated','rfq')), default_basis text NOT NULL, allows_spot_price boolean NOT NULL DEFAULT true, requires_resource_hold boolean NOT NULL DEFAULT false, spot_approval_role text NOT NULL DEFAULT 'sales_manager', params jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','retired')), notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.pricing_service_types ( code text PRIMARY KEY, label text NOT NULL, sort_order integer NOT NULL DEFAULT 100, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.public_meeting_bookings ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_name text NOT NULL, client_email text NOT NULL, company text, phone text, topic text NOT NULL, starts_at timestamptz NOT NULL, duration_minutes int NOT NULL DEFAULT 30, join_url text, external_event_id text, status text NOT NULL DEFAULT 'pending', failure_reason text, ip_hash text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rec_comm_dispatch_attempts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.rec_comm_requests(id) ON DELETE CASCADE, attempt integer NOT NULL, outcome text NOT NULL, provider text, provider_message_id text, error text, detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rec_comm_attempt_once UNIQUE (request_id, attempt), CONSTRAINT rec_comm_attempt_outcome_chk CHECK (outcome IN ('provider_accepted','suppressed','failed')) );
CREATE TABLE IF NOT EXISTS public.rename_alert_dispatch_log ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), dedup_key TEXT NOT NULL, source TEXT NOT NULL, severity TEXT NOT NULL, title TEXT NOT NULL, suppressed BOOLEAN NOT NULL DEFAULT false, slack_sent BOOLEAN NOT NULL DEFAULT false, email_sent BOOLEAN NOT NULL DEFAULT false, cooldown_expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rental_booking_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES public.rental_bookings(id) ON DELETE CASCADE, event_type text NOT NULL, detail jsonb NOT NULL DEFAULT '{}'::jsonb, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ride_categories ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE, name text NOT NULL, tier text NOT NULL CHECK (tier IN ('basic','standard','plus','executive','tour','shuttle','coaster','bus')), seats integer NOT NULL CHECK (seats > 0), vehicle_class text NOT NULL, image_url text, base_description text, sort_order integer NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ride_interventions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trip_id uuid, driver_id uuid, rider_id uuid, intervention text NOT NULL, reason text, actor_id uuid REFERENCES auth.users(id) ON DELETE SET NULL, outcome text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ride_receivables ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id), intent_id uuid NOT NULL REFERENCES public.ride_payment_intents(id), amount_cents bigint NOT NULL CHECK (amount_cents > 0), settled_cents bigint NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'KES', state public.ride_receivable_state NOT NULL DEFAULT 'OPEN', due_date date NOT NULL, invoice_id uuid REFERENCES public.corporate_invoices(id), reservation_id uuid REFERENCES public.corporate_credit_reservations(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (intent_id) );
CREATE TABLE IF NOT EXISTS public.rider_badges ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, description text, icon text, criteria jsonb NOT NULL DEFAULT '{}'::jsonb, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rider_behavior_scores ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rider_id uuid NOT NULL, window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, cancellations int NOT NULL DEFAULT 0, no_shows int NOT NULL DEFAULT 0, complaints int NOT NULL DEFAULT 0, trips_completed int NOT NULL DEFAULT 0, score numeric NOT NULL DEFAULT 0, computed_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rider_device_fingerprints ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rider_id uuid NOT NULL, fingerprint_hash text NOT NULL, device_type text, os text, os_version text, app_version text, ip_address inet, user_agent text, trust_level text NOT NULL DEFAULT 'unverified', first_seen_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), is_blocked boolean NOT NULL DEFAULT false, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (rider_id, fingerprint_hash) );
CREATE TABLE IF NOT EXISTS public.rider_fraud_signals ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rider_id uuid NOT NULL, signal_type text NOT NULL, severity text NOT NULL DEFAULT 'low', source text, context jsonb NOT NULL DEFAULT '{}'::jsonb, trip_id uuid, device_id uuid, detected_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rider_locations (rider_id uuid PRIMARY KEY, lat double precision NOT NULL, lng double precision NOT NULL, accuracy_m numeric(6,2), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.rider_points ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rider_id uuid NOT NULL, entry_type text NOT NULL, points int NOT NULL, reason text, reference_type text, reference_id uuid, expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rider_risk_profiles ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rider_id uuid NOT NULL UNIQUE, risk_tier text NOT NULL DEFAULT 'low', risk_score numeric NOT NULL DEFAULT 0, flags jsonb NOT NULL DEFAULT '[]'::jsonb, last_assessed_at timestamptz, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rider_safety_incidents ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rider_id uuid NOT NULL, trip_id uuid, driver_id uuid, incident_type text NOT NULL, severity text NOT NULL DEFAULT 'low', description text, reported_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'open', assigned_to uuid, resolution text, resolved_at timestamptz, evidence jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rider_sos_alerts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rider_id uuid NOT NULL, trip_id uuid, triggered_at timestamptz NOT NULL DEFAULT now(), latitude numeric, longitude numeric, status text NOT NULL DEFAULT 'open', channel text NOT NULL DEFAULT 'in_app', responder_id uuid, responded_at timestamptz, resolution_notes text, context jsonb NOT NULL DEFAULT '{}'::jsonb, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rider_tiers ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, rank int NOT NULL, min_points int NOT NULL DEFAULT 0, perks jsonb NOT NULL DEFAULT '[]'::jsonb, multiplier numeric NOT NULL DEFAULT 1.0, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rider_trust_scores ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rider_id uuid NOT NULL UNIQUE, composite_score numeric NOT NULL DEFAULT 50, behavior_component numeric NOT NULL DEFAULT 0, fraud_component numeric NOT NULL DEFAULT 0, device_component numeric NOT NULL DEFAULT 0, loyalty_component numeric NOT NULL DEFAULT 0, tier text NOT NULL DEFAULT 'standard', model_version text, computed_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.trip_location_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trip_id uuid NOT NULL, event_type text NOT NULL, lat double precision, lng double precision, occurred_at timestamptz NOT NULL DEFAULT now(), payload jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS public.trip_share_access_log ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), token_hash text NOT NULL, trip_booking_id uuid, ip inet, user_agent text, outcome text NOT NULL CHECK (outcome IN ('ok','invalid','expired','revoked','exhausted','pin_required','pin_wrong')), accessed_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.trip_share_lockouts ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scope text NOT NULL CHECK (scope IN ('ip','token')), key text NOT NULL, failed_count integer NOT NULL DEFAULT 0, locked_until timestamptz, last_failed_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (scope, key) );
CREATE TABLE IF NOT EXISTS public.trip_share_tokens ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), trip_booking_id uuid NOT NULL, owner_id uuid NOT NULL, token_hash text NOT NULL UNIQUE, pin_hash text, max_uses int NOT NULL DEFAULT 1 CHECK (max_uses >= 1), used_count int NOT NULL DEFAULT 0, expires_at timestamptz NOT NULL, revoked_at timestamptz, revoked_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ap360_categories ( code text PRIMARY KEY, family_code text NOT NULL REFERENCES public.ap360_families(code) ON DELETE RESTRICT, label text NOT NULL, engine_code text NOT NULL REFERENCES public.ap360_engines(code) ON DELETE RESTRICT, reference_low numeric(14,2), reference_high numeric(14,2), reference_unit text, capacity integer, sort_order integer NOT NULL DEFAULT 100, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT ap360_categories_band CHECK ( reference_low IS NULL OR reference_high IS NULL OR reference_high >= reference_low) );
CREATE TABLE IF NOT EXISTS public.asset_pricing_bands ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, version_id uuid NOT NULL REFERENCES public.asset_pricing_versions(id) ON DELETE CASCADE, asset_class text NOT NULL, vehicle_key text NOT NULL, label text NOT NULL, fleet_group text NOT NULL DEFAULT 'van', seats integer NOT NULL DEFAULT 1 CHECK (seats > 0), basis text NOT NULL DEFAULT 'day_plus_mileage' CHECK (basis IN ('block_hour','day','day_plus_mileage','voyage_day')), category_code text REFERENCES public.commercial_vehicle_categories(code) ON DELETE SET NULL, service_code text NOT NULL DEFAULT 'day_trip', base_kes numeric(14,2) NOT NULL CHECK (base_kes > 0), min_kes numeric(14,2) NOT NULL CHECK (min_kes > 0), max_kes numeric(14,2) NOT NULL CHECK (max_kes > 0), per_km_kes numeric(12,2) NOT NULL DEFAULT 0 CHECK (per_km_kes >= 0), extra_hour_kes numeric(12,2) NOT NULL DEFAULT 0 CHECK (extra_hour_kes >= 0), included_km_per_day integer NOT NULL DEFAULT 0 CHECK (included_km_per_day >= 0), corporate_discount_pct numeric(6,3) NOT NULL DEFAULT 0 CHECK (corporate_discount_pct BETWEEN 0 AND 50), weekend_multiplier numeric(6,3) NOT NULL DEFAULT 1 CHECK (weekend_multiplier BETWEEN 0.5 AND 3), holiday_multiplier numeric(6,3) NOT NULL DEFAULT 1 CHECK (holiday_multiplier BETWEEN 0.5 AND 3), peak_multiplier numeric(6,3) NOT NULL DEFAULT 1 CHECK (peak_multiplier BETWEEN 0.5 AND 3), max_demand_multiplier numeric(6,3) NOT NULL DEFAULT 1 CHECK (max_demand_multiplier BETWEEN 0.5 AND 3), platform_fee_pct numeric(6,3) NOT NULL DEFAULT 0 CHECK (platform_fee_pct BETWEEN 0 AND 40), vat_pct numeric(6,3) NOT NULL DEFAULT 0 CHECK (vat_pct BETWEEN 0 AND 30), operator_override_tolerance_pct numeric(6,3) NOT NULL DEFAULT 25 CHECK (operator_override_tolerance_pct BETWEEN 0 AND 100), active boolean NOT NULL DEFAULT true, note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (version_id, vehicle_key), CONSTRAINT asset_pricing_bands_band_order CHECK (max_kes >= min_kes), CONSTRAINT asset_pricing_bands_base_in_band CHECK (base_kes BETWEEN min_kes AND max_kes) );
CREATE TABLE IF NOT EXISTS public.asset_pricing_fee_components ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, version_id uuid NOT NULL REFERENCES public.asset_pricing_versions(id) ON DELETE CASCADE, asset_class text NOT NULL, fee_key text NOT NULL, label text NOT NULL, unit text NOT NULL CHECK (unit IN ('per_trip','per_day','per_night','per_km','per_movement','per_passenger','per_hour')), amount_kes numeric(12,2) NOT NULL CHECK (amount_kes >= 0), optional boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (version_id, asset_class, fee_key) );
CREATE TABLE IF NOT EXISTS public.city_pricing_rules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_slug text NOT NULL REFERENCES public.ride_categories(slug) ON DELETE CASCADE, city text NOT NULL, country_code text NOT NULL DEFAULT 'KE', base_fare_override numeric(10,2), per_km_override numeric(10,2), per_min_override numeric(10,2), minimum_fare_override numeric(10,2), fuel_cost_per_km numeric(10,2) NOT NULL, maintenance_per_km numeric(10,2) NOT NULL, insurance_monthly numeric(10,2) NOT NULL, avg_trips_per_hour numeric(5,2) NOT NULL DEFAULT 2.0, avg_km_per_trip numeric(5,2) NOT NULL DEFAULT 7.0, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (category_slug, city) );
CREATE TABLE IF NOT EXISTS public.commercial_document_dispatches ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES public.commercial_documents(id), transaction_id uuid NOT NULL REFERENCES public.commercial_transactions(id), transaction_ref text NOT NULL, message_id text NOT NULL, channel text NOT NULL DEFAULT 'email' CHECK (channel IN ('email')), recipient_email text NOT NULL, subject text NOT NULL, template_key text NOT NULL, template_version text NOT NULL DEFAULT '1.0', pdf_sha256 text, status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','sent','delivered','bounced','failed','suppressed')), attempt_count integer NOT NULL DEFAULT 0, last_attempt_at timestamptz, error_message text, provider text NOT NULL DEFAULT 'smtp2go', provider_message_id text, actor_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT commercial_document_dispatches_message_uidx UNIQUE (message_id), CONSTRAINT commercial_document_dispatches_hash_fmt CHECK (pdf_sha256 IS NULL OR pdf_sha256 ~ '^[0-9a-f]{64}$') );
CREATE TABLE IF NOT EXISTS public.corporate_employees ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, user_id uuid, department_id uuid REFERENCES public.corporate_departments(id) ON DELETE SET NULL, email text NOT NULL, full_name text, phone text, employee_code text, role public.corporate_employee_role NOT NULL DEFAULT 'corporate_employee', status public.corporate_employee_status NOT NULL DEFAULT 'invited', monthly_cap_cents bigint, per_trip_cap_cents bigint, manager_user_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, invited_at timestamptz, activated_at timestamptz, removed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (corporate_id, email) );
CREATE TABLE IF NOT EXISTS public.dispatch_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.dispatch_requests(id) ON DELETE CASCADE, driver_id uuid NOT NULL, vehicle_id uuid, assigned_at timestamptz NOT NULL DEFAULT now(), accepted_at timestamptz, arrived_at timestamptz, started_at timestamptz, completed_at timestamptz, cancelled_at timestamptz, cancel_reason text, trip_distance_m int, trip_duration_s int);
CREATE TABLE IF NOT EXISTS public.dispatch_candidates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.dispatch_requests(id) ON DELETE CASCADE, driver_id uuid NOT NULL, rank int NOT NULL, distance_m int, eta_seconds int, score numeric(8,4), status public.dispatch_candidate_status NOT NULL DEFAULT 'SCORED', offered_at timestamptz, responded_at timestamptz, reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.dispatch_engine_runs ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, request_id UUID NOT NULL REFERENCES public.dispatch_requests(id) ON DELETE CASCADE, rule_version TEXT, candidates_considered INTEGER NOT NULL DEFAULT 0, candidates_offered INTEGER NOT NULL DEFAULT 0, winner_driver_id UUID, outcome TEXT NOT NULL, duration_ms INTEGER, notes JSONB NOT NULL DEFAULT '{}'::jsonb, started_at TIMESTAMPTZ NOT NULL DEFAULT now(), finished_at TIMESTAMPTZ, CONSTRAINT chk_engine_outcome CHECK (outcome IN ('ASSIGNED','NO_SUPPLY','EXPIRED','CANCELLED','ERROR')) );
CREATE TABLE IF NOT EXISTS public.dispatch_hex_assignments ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), driver_id UUID NOT NULL, hex_id UUID NOT NULL REFERENCES public.marketplace_hex_cells(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'available', vehicle_type TEXT, last_location_lat NUMERIC(10,7), last_location_lng NUMERIC(10,7), entered_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(), metadata JSONB NOT NULL DEFAULT '{}'::jsonb, UNIQUE(driver_id) );
CREATE TABLE IF NOT EXISTS public.dispatch_rule_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rule_id uuid NOT NULL REFERENCES public.dispatch_rules(id) ON DELETE CASCADE, version int NOT NULL, config jsonb NOT NULL, ab_test_group text, weight_percentage int NOT NULL DEFAULT 100 CHECK (weight_percentage BETWEEN 0 AND 100), created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (rule_id, version));
CREATE TABLE IF NOT EXISTS public.dispatch_sim_results ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, scenario_id UUID NOT NULL REFERENCES public.dispatch_sim_scenarios(id) ON DELETE CASCADE, rule_version TEXT, total_requests INTEGER NOT NULL DEFAULT 0, assigned INTEGER NOT NULL DEFAULT 0, expired INTEGER NOT NULL DEFAULT 0, no_supply INTEGER NOT NULL DEFAULT 0, avg_assign_ms INTEGER, avg_eta_seconds INTEGER, avg_score NUMERIC(8,4), details JSONB NOT NULL DEFAULT '{}'::jsonb, started_at TIMESTAMPTZ NOT NULL DEFAULT now(), finished_at TIMESTAMPTZ );
CREATE TABLE IF NOT EXISTS public.fin_reconciliation_matches ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), intent_id uuid NOT NULL REFERENCES public.ride_payment_intents(id), receipt_id uuid NOT NULL REFERENCES public.fin_bank_receipts(id), matched_amount_cents bigint NOT NULL, variance_cents bigint NOT NULL, state text NOT NULL CHECK (state IN ('MATCHED','VARIANCE')), note text, reconciled_by uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (intent_id, receipt_id) );
CREATE TABLE IF NOT EXISTS public.freight_route_commitments ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), commitment_code text NOT NULL UNIQUE, route_id uuid NOT NULL REFERENCES public.freight_repeat_routes(id) ON DELETE CASCADE, customer_id uuid NOT NULL, weekday_mask integer[] NOT NULL, daily_weight_kg numeric(12,2) NOT NULL, daily_volume_cbm numeric(12,3) NOT NULL DEFAULT 0, starts_on date NOT NULL, ends_on date NOT NULL, status text NOT NULL DEFAULT 'ACTIVE', template_order_id uuid REFERENCES public.delivery_orders(id) ON DELETE SET NULL, notes text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT rc_status CHECK (status = ANY (ARRAY['ACTIVE','SUSPENDED','COMPLETED','CANCELLED'])), CONSTRAINT rc_weight CHECK (daily_weight_kg > 0), CONSTRAINT rc_dates CHECK (ends_on >= starts_on), CONSTRAINT rc_weekdays CHECK (cardinality(weekday_mask) > 0) );
CREATE TABLE IF NOT EXISTS public.freight_route_instances ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), instance_code text NOT NULL UNIQUE, route_id uuid NOT NULL REFERENCES public.freight_repeat_routes(id) ON DELETE CASCADE, service_date date NOT NULL, scheduled_departure timestamptz NOT NULL, scheduled_arrival timestamptz, booking_cutoff_at timestamptz NOT NULL, vehicle_class text NOT NULL, planned_capacity_kg numeric(12,2) NOT NULL, planned_volume_cbm numeric(12,3) NOT NULL DEFAULT 0, reserved_capacity_kg numeric(12,2) NOT NULL DEFAULT 0, reserved_volume_cbm numeric(12,3) NOT NULL DEFAULT 0, available_capacity_kg numeric(12,2) GENERATED ALWAYS AS (planned_capacity_kg - reserved_capacity_kg) STORED, available_volume_cbm numeric(12,3) GENERATED ALWAYS AS (planned_volume_cbm - reserved_volume_cbm) STORED, allocation_count integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'PLANNED', dispatch_request_id uuid REFERENCES public.logistics_dispatch_requests(id) ON DELETE SET NULL, vehicle_id uuid REFERENCES public.vehicles(id), driver_id uuid REFERENCES public.drivers(id), manifest_version integer NOT NULL DEFAULT 0, manifest_locked_at timestamptz, actual_departure timestamptz, actual_arrival timestamptz, completed_at timestamptz, cancellation_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT ri_unique_departure UNIQUE (route_id, service_date), CONSTRAINT ri_status CHECK (status = ANY (ARRAY[ 'PLANNED','OPEN_FOR_BOOKING','CAPACITY_RESERVED','MANIFEST_CLOSING','MANIFEST_LOCKED', 'DISPATCHED','DEPARTED','IN_TRANSIT','ARRIVED','COMPLETED','SUSPENDED','CANCELLED','DELAYED'])), CONSTRAINT ri_reserved_nonneg CHECK (reserved_capacity_kg >= 0 AND reserved_volume_cbm >= 0), CONSTRAINT ri_capacity CHECK (planned_capacity_kg > 0) );
CREATE TABLE IF NOT EXISTS public.logistics_exceptions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exception_number text NOT NULL UNIQUE DEFAULT 'LEX-' || to_char(now(), 'YYYYMM') || '-' || lpad(nextval('public.logistics_exception_seq')::text, 6, '0'), order_id uuid, package_id uuid REFERENCES public.packages(id) ON DELETE SET NULL, attempt_id uuid REFERENCES public.logistics_delivery_attempts(id) ON DELETE SET NULL, kind text NOT NULL, severity text NOT NULL DEFAULT 'medium' CHECK (severity IN ('low','medium','high','critical')), owner_role text NOT NULL DEFAULT 'operations_admin', status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','investigating','waiting_customer','waiting_partner','resolved','cancelled')), reason_code text, narrative text, sla_due_at timestamptz, opened_by uuid, resolution text, resolved_by uuid, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_match_candidates ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), match_run_id uuid NOT NULL REFERENCES public.logistics_match_runs(id) ON DELETE CASCADE, vehicle_id uuid NOT NULL, driver_id uuid, eligible boolean NOT NULL, score numeric(6,2), rank integer, rejection_reasons text[] NOT NULL DEFAULT '{}', evidence jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.marketplace_eta_calibration ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hex_id UUID NOT NULL REFERENCES public.marketplace_hex_cells(id) ON DELETE CASCADE, ride_type TEXT, predicted_eta_seconds INTEGER NOT NULL, actual_eta_seconds INTEGER NOT NULL, error_seconds INTEGER NOT NULL, error_pct NUMERIC(6,3), sample_count INTEGER NOT NULL DEFAULT 1, computed_at TIMESTAMPTZ NOT NULL DEFAULT now(), metadata JSONB NOT NULL DEFAULT '{}'::jsonb );
CREATE TABLE IF NOT EXISTS public.marketplace_surge_events ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hex_id UUID NOT NULL REFERENCES public.marketplace_hex_cells(id) ON DELETE CASCADE, ride_type TEXT, previous_multiplier NUMERIC(4,2), new_multiplier NUMERIC(4,2) NOT NULL, trigger TEXT NOT NULL, supply_count INTEGER, demand_count INTEGER, ratio NUMERIC(6,3), actor_id UUID, notes TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.marketplace_surge_multipliers ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hex_id UUID NOT NULL REFERENCES public.marketplace_hex_cells(id) ON DELETE CASCADE, ride_type TEXT, multiplier NUMERIC(4,2) NOT NULL DEFAULT 1.00, reason TEXT, supply_demand_ratio NUMERIC(6,3), effective_from TIMESTAMPTZ NOT NULL DEFAULT now(), effective_until TIMESTAMPTZ, is_active BOOLEAN NOT NULL DEFAULT true, source TEXT NOT NULL DEFAULT 'auto', metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_by UUID, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.meeting_booking_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES public.public_meeting_bookings(id) ON DELETE CASCADE, event text NOT NULL, from_status text, to_status text, actor_user_id uuid, actor_label text NOT NULL DEFAULT 'system', detail jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.pricing_competitor_observations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), competitor text NOT NULL, service_code text NOT NULL REFERENCES public.pricing_service_types(code) ON DELETE RESTRICT, scope_label text NOT NULL DEFAULT '', category_code text, pricing_basis text NOT NULL DEFAULT 'per_day', amount numeric(14,2) NOT NULL CHECK (amount > 0), currency text NOT NULL DEFAULT 'KES', observed_on date NOT NULL, source text NOT NULL, customer_segment text, notes text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.pricing_components ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, rule_set_id uuid NOT NULL REFERENCES public.pricing_rule_sets(id) ON DELETE CASCADE, kind text NOT NULL CHECK (kind = ANY (ARRAY['fee','tax','surcharge','discount','floor','commission'])), code text NOT NULL, label text NOT NULL, calc text NOT NULL CHECK (calc = ANY (ARRAY['percentage','fixed','multiplier'])), value numeric(14,4) NOT NULL CHECK (value >= 0), basis text NOT NULL DEFAULT 'adjusted_base' CHECK (basis = ANY (ARRAY['base','adjusted_base','pre_tax_subtotal','total'])), scope jsonb NOT NULL DEFAULT '{}'::jsonb, priority integer NOT NULL DEFAULT 100, stackable boolean NOT NULL DEFAULT true, requires_code boolean NOT NULL DEFAULT false, min_amount numeric(14,2), max_amount numeric(14,2), active boolean NOT NULL DEFAULT true, reason text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (rule_set_id, code) );
CREATE TABLE IF NOT EXISTS public.pricing_cost_baselines ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_code text NOT NULL REFERENCES public.pricing_service_types(code) ON DELETE RESTRICT, scope_label text NOT NULL DEFAULT '', category_code text NOT NULL REFERENCES public.commercial_vehicle_categories(code) ON DELETE RESTRICT, pricing_basis text NOT NULL DEFAULT 'per_day', driver_cost numeric(14,2) NOT NULL DEFAULT 0, fuel_cost numeric(14,2) NOT NULL DEFAULT 0, tolls_parking numeric(14,2) NOT NULL DEFAULT 0, supplier_cost numeric(14,2) NOT NULL DEFAULT 0, operational_cost numeric(14,2) NOT NULL DEFAULT 0, platform_cost numeric(14,2) NOT NULL DEFAULT 0, currency text NOT NULL DEFAULT 'KES', effective_from date, effective_to date, source text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.pricing_customer_rates ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES public.crm_accounts(id) ON DELETE CASCADE, contract_instance_id uuid REFERENCES public.commercial_contract_instances(id) ON DELETE SET NULL, rate_kind text NOT NULL CHECK (rate_kind IN ('contract','customer','volume','promotional','project','seasonal','competitive','spot')), service_code text NOT NULL REFERENCES public.pricing_service_types(code) ON DELETE RESTRICT, scope_label text NOT NULL DEFAULT '', category_code text NOT NULL REFERENCES public.commercial_vehicle_categories(code) ON DELETE RESTRICT, pricing_basis text NOT NULL DEFAULT 'per_day', amount numeric(14,2) NOT NULL CHECK (amount > 0), currency text NOT NULL DEFAULT 'KES', min_quantity numeric(10,2) NOT NULL DEFAULT 1, effective_from date, effective_to date, status text NOT NULL DEFAULT 'active' CHECK (status IN ('draft','active','expired','withdrawn')), reason text, created_by uuid, approved_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.pricing_models ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_slug text NOT NULL REFERENCES public.ride_categories(slug) ON DELETE CASCADE, currency text NOT NULL DEFAULT 'KES', base_fare numeric(10,2) NOT NULL, per_km numeric(10,2) NOT NULL, per_min numeric(10,2) NOT NULL, minimum_fare numeric(10,2) NOT NULL, booking_fee numeric(10,2) NOT NULL DEFAULT 0, cancellation_fee numeric(10,2) NOT NULL DEFAULT 0, commission_pct numeric(5,2) NOT NULL DEFAULT 18.00 CHECK (commission_pct BETWEEN 0 AND 50), effective_from timestamptz NOT NULL DEFAULT now(), effective_to timestamptz, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.pricing_negotiations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES public.crm_accounts(id) ON DELETE CASCADE, opportunity_id uuid REFERENCES public.commercial_opportunities(id) ON DELETE SET NULL, quotation_id uuid REFERENCES public.commercial_quotations(id) ON DELETE SET NULL, rate_card_id uuid REFERENCES public.commercial_rate_cards(id) ON DELETE SET NULL, rate_card_version text, service_code text NOT NULL, scope_label text NOT NULL DEFAULT '', category_code text NOT NULL, pricing_basis text NOT NULL DEFAULT 'per_day', quantity numeric(10,2) NOT NULL DEFAULT 1, recommended_amount numeric(14,2) NOT NULL, customer_rate_amount numeric(14,2), proposed_amount numeric(14,2) NOT NULL CHECK (proposed_amount >= 0), final_amount numeric(14,2), variance_amount numeric(14,2) NOT NULL, variance_percent numeric(8,2) NOT NULL, price_source text NOT NULL, commercial_reason text, estimated_cost numeric(14,2), margin_amount numeric(14,2), margin_percent numeric(8,2), guardrail_code text, guardrail_action text NOT NULL DEFAULT 'none', required_role text, approval_status text NOT NULL DEFAULT 'not_required' CHECK (approval_status IN ('not_required','pending','approved','rejected')), decided_by uuid, decided_at timestamptz, decision_note text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.pricing_quote_snapshots ( id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, quote_ref text, domain text NOT NULL, inputs jsonb NOT NULL, result jsonb NOT NULL, rate_card_id uuid REFERENCES public.commercial_rate_cards(id) ON DELETE SET NULL, rate_card_version text, rule_set_id uuid REFERENCES public.pricing_rule_sets(id) ON DELETE SET NULL, rule_set_version text, currency text NOT NULL DEFAULT 'KES', total numeric(14,2) NOT NULL, calculated_by uuid, calculated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.rider_memberships ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rider_id uuid NOT NULL, tier_id uuid NOT NULL REFERENCES public.rider_tiers(id), started_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz, lifetime_points int NOT NULL DEFAULT 0, current_points int NOT NULL DEFAULT 0, is_active boolean NOT NULL DEFAULT true, badges jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.surge_rules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), city text NOT NULL, category_slug text NOT NULL REFERENCES public.ride_categories(slug) ON DELETE CASCADE, hour_of_week integer NOT NULL CHECK (hour_of_week BETWEEN 0 AND 167), multiplier numeric(4,2) NOT NULL DEFAULT 1.00 CHECK (multiplier BETWEEN 0.5 AND 5.0), reason text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (city, category_slug, hour_of_week) );
CREATE TABLE IF NOT EXISTS public.ap360_profiles ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_code text NOT NULL REFERENCES public.ap360_categories(code) ON DELETE RESTRICT, code text NOT NULL UNIQUE, label text NOT NULL, currency text NOT NULL DEFAULT 'KES', geography text NOT NULL DEFAULT 'KE', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT ap360_profiles_unique_scope UNIQUE (category_code, geography) );
CREATE TABLE IF NOT EXISTS public.corporate_ride_policies ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, name text NOT NULL, description text, scope public.corporate_policy_scope NOT NULL DEFAULT 'corporate', department_id uuid REFERENCES public.corporate_departments(id) ON DELETE CASCADE, employee_id uuid REFERENCES public.corporate_employees(id) ON DELETE CASCADE, priority integer NOT NULL DEFAULT 100, active boolean NOT NULL DEFAULT true, effective_from timestamptz NOT NULL DEFAULT now(), effective_to timestamptz, created_by uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.dispatch_eta_estimates ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, request_id UUID NOT NULL REFERENCES public.dispatch_requests(id) ON DELETE CASCADE, candidate_id UUID REFERENCES public.dispatch_candidates(id) ON DELETE CASCADE, driver_id UUID NOT NULL, distance_m INTEGER NOT NULL, eta_seconds INTEGER NOT NULL, confidence NUMERIC(4,3) NOT NULL DEFAULT 0.5, model_version TEXT NOT NULL DEFAULT 'haversine-v1', created_at TIMESTAMPTZ NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.dispatch_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid REFERENCES public.dispatch_requests(id) ON DELETE CASCADE, candidate_id uuid REFERENCES public.dispatch_candidates(id) ON DELETE SET NULL, event_type text NOT NULL, actor_id uuid, payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.dispatch_offer_timeouts ( id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, candidate_id UUID NOT NULL REFERENCES public.dispatch_candidates(id) ON DELETE CASCADE, request_id UUID NOT NULL REFERENCES public.dispatch_requests(id) ON DELETE CASCADE, driver_id UUID NOT NULL, expires_at TIMESTAMPTZ NOT NULL, resolved_at TIMESTAMPTZ, outcome TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CONSTRAINT chk_timeout_outcome CHECK (outcome IS NULL OR outcome IN ('ACCEPTED','REJECTED','EXPIRED')) );
CREATE TABLE IF NOT EXISTS public.dispatch_rejections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL REFERENCES public.dispatch_candidates(id) ON DELETE CASCADE, driver_id uuid NOT NULL, reason_code text NOT NULL, reason_text text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.dispatch_scores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_id uuid NOT NULL REFERENCES public.dispatch_candidates(id) ON DELETE CASCADE, factor text NOT NULL, weight numeric(6,3) NOT NULL, value numeric(10,3) NOT NULL, contribution numeric(10,3) NOT NULL, rule_version text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.freight_route_allocations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), allocation_code text NOT NULL UNIQUE, route_instance_id uuid NOT NULL REFERENCES public.freight_route_instances(id) ON DELETE CASCADE, order_id uuid NOT NULL REFERENCES public.delivery_orders(id) ON DELETE CASCADE, consignment_id uuid REFERENCES public.freight_consignments(id) ON DELETE SET NULL, quote_id uuid REFERENCES public.freight_quotations(id) ON DELETE SET NULL, customer_id uuid NOT NULL, commitment_id uuid, allocated_weight_kg numeric(12,2) NOT NULL, allocated_volume_cbm numeric(12,3) NOT NULL DEFAULT 0, pieces integer, status text NOT NULL DEFAULT 'RESERVED', release_reason text, released_at timestamptz, idempotency_key text UNIQUE, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT ra_status CHECK (status = ANY (ARRAY['RESERVED','MANIFESTED','LOADED','DELIVERED','RELEASED','CANCELLED'])), CONSTRAINT ra_weight CHECK (allocated_weight_kg > 0), CONSTRAINT ra_volume CHECK (allocated_volume_cbm >= 0) );
CREATE TABLE IF NOT EXISTS public.freight_route_exceptions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route_instance_id uuid REFERENCES public.freight_route_instances(id) ON DELETE CASCADE, route_id uuid REFERENCES public.freight_repeat_routes(id) ON DELETE CASCADE, commitment_id uuid REFERENCES public.freight_route_commitments(id) ON DELETE CASCADE, exception_type text NOT NULL, severity text NOT NULL DEFAULT 'MEDIUM', status text NOT NULL DEFAULT 'OPEN', detail text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, raised_by uuid, resolved_by uuid, resolved_at timestamptz, resolution_note text, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT fex_type CHECK (exception_type = ANY (ARRAY[ 'DEPARTURE_MISSED','CAPACITY_SHORTFALL','VEHICLE_UNAVAILABLE','DRIVER_UNAVAILABLE', 'NO_CAPACITY_MATCHED','UNDERUTILISED','ROUTE_SUSPENDED','COMMITMENT_UNFULFILLED'])), CONSTRAINT fex_sev CHECK (severity = ANY (ARRAY['LOW','MEDIUM','HIGH','CRITICAL'])), CONSTRAINT fex_status CHECK (status = ANY (ARRAY['OPEN','ACKNOWLEDGED','RESOLVED','CANCELLED'])) );
CREATE TABLE IF NOT EXISTS public.freight_route_manifests ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route_instance_id uuid NOT NULL REFERENCES public.freight_route_instances(id) ON DELETE CASCADE, version integer NOT NULL, reason text, vehicle_id uuid, driver_id uuid, capacity_kg numeric(12,2) NOT NULL, booked_kg numeric(12,2) NOT NULL, available_kg numeric(12,2) NOT NULL, line_count integer NOT NULL, lines jsonb NOT NULL DEFAULT '[]'::jsonb, changes jsonb NOT NULL DEFAULT '{}'::jsonb, actor_id uuid, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT frm_version UNIQUE (route_instance_id, version) );
CREATE TABLE IF NOT EXISTS public.logistics_route_stops ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route_id uuid NOT NULL REFERENCES public.logistics_routes(id) ON DELETE CASCADE, route_version_id uuid NOT NULL REFERENCES public.logistics_route_versions(id) ON DELETE CASCADE, sequence integer NOT NULL CHECK (sequence > 0), stop_type text NOT NULL CHECK (stop_type IN ('pickup','delivery','return','hub','waypoint')), hub_id uuid REFERENCES public.logistics_hubs(id) ON DELETE SET NULL, address text, lat numeric, lng numeric, contact_name text, contact_phone text, instructions text, service_window_start timestamptz, service_window_end timestamptz, planned_arrival timestamptz, eta timestamptz, eta_source text CHECK (eta_source IS NULL OR eta_source IN ('planned','optimizer','dispatch','telemetry','manual')), eta_revised_at timestamptz, actual_arrival timestamptz, departed_at timestamptz, status text NOT NULL DEFAULT 'PLANNED' CHECK (status IN ('PLANNED','ASSIGNED','EN_ROUTE','ARRIVED','SERVICE_STARTED','COMPLETED','FAILED','SKIPPED','CANCELLED')), exception_id uuid REFERENCES public.logistics_exceptions(id) ON DELETE SET NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (route_version_id, sequence) DEFERRABLE INITIALLY DEFERRED );
CREATE TABLE IF NOT EXISTS public.ap360_versions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL REFERENCES public.ap360_profiles(id) ON DELETE CASCADE, version integer NOT NULL, status text NOT NULL DEFAULT 'draft', engine_code text NOT NULL REFERENCES public.ap360_engines(code), params jsonb NOT NULL DEFAULT '{}'::jsonb, commission_pct numeric(6,3) NOT NULL DEFAULT 0, max_discount_pct numeric(6,3) NOT NULL DEFAULT 0, demand_ceiling numeric(6,3) NOT NULL DEFAULT 1.20, override_tolerance_pct numeric(6,3) NOT NULL DEFAULT 10, target_margin_pct numeric(6,3) NOT NULL DEFAULT 15, fuel_policy text NOT NULL DEFAULT 'excluded', tax_rule_code text, effective_from timestamptz NOT NULL DEFAULT now(), effective_to timestamptz, reason text NOT NULL DEFAULT '', source text NOT NULL DEFAULT 'admin_ui', created_by uuid, approved_by uuid, approved_at timestamptz, published_by uuid, published_at timestamptz, superseded_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT ap360_versions_unique UNIQUE (profile_id, version), CONSTRAINT ap360_versions_status CHECK (status IN ('draft','validating','submitted','approved','published','scheduled','active','superseded','archived','rejected')), CONSTRAINT ap360_versions_fuel CHECK (fuel_policy IN ('included','excluded','surcharge','indexed','operator_supplied')), CONSTRAINT ap360_versions_commission CHECK (commission_pct >= 0 AND commission_pct <= 30), CONSTRAINT ap360_versions_discount CHECK (max_discount_pct >= 0 AND max_discount_pct <= 30), CONSTRAINT ap360_versions_ceiling CHECK (demand_ceiling >= 1 AND demand_ceiling <= 3), CONSTRAINT ap360_versions_tolerance CHECK (override_tolerance_pct >= 0 AND override_tolerance_pct <= 100), CONSTRAINT ap360_versions_margin CHECK (target_margin_pct >= 0 AND target_margin_pct <= 100), CONSTRAINT ap360_versions_window CHECK (effective_to IS NULL OR effective_to > effective_from) );
CREATE TABLE IF NOT EXISTS public.corporate_policy_rules ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), policy_id uuid NOT NULL REFERENCES public.corporate_ride_policies(id) ON DELETE CASCADE, rule_kind text NOT NULL CHECK (rule_kind IN ( 'ride_type_allow','ride_type_block', 'max_fare_per_trip','max_distance_km', 'time_window','day_of_week', 'monthly_spend_cap','weekly_spend_cap', 'requires_approval_above','geo_allowlist','geo_blocklist' )), allowed_ride_types text[], blocked_ride_types text[], max_fare_cents bigint, max_distance_km numeric, time_start time, time_end time, days_of_week integer[], cap_cents bigint, threshold_cents bigint, geo_zones text[], config jsonb NOT NULL DEFAULT '{}'::jsonb, severity text NOT NULL DEFAULT 'block' CHECK (severity IN ('warn','approval','block')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.freight_route_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route_id uuid REFERENCES public.freight_repeat_routes(id) ON DELETE CASCADE, route_instance_id uuid REFERENCES public.freight_route_instances(id) ON DELETE CASCADE, allocation_id uuid REFERENCES public.freight_route_allocations(id) ON DELETE SET NULL, event_type text NOT NULL, previous_status text, new_status text, actor_id uuid, actor_role text, reason text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, occurred_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_route_deviations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route_id uuid NOT NULL REFERENCES public.logistics_routes(id) ON DELETE CASCADE, stop_id uuid REFERENCES public.logistics_route_stops(id) ON DELETE SET NULL, kind text NOT NULL CHECK (kind IN ('route_deviation','missed_stop','unexpected_stop','sequence_violation','route_abandonment')), severity text NOT NULL DEFAULT 'medium' CHECK (severity IN ('low','medium','high')), distance_m numeric, narrative text, exception_id uuid REFERENCES public.logistics_exceptions(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','acknowledged','resolved','dismissed')), detected_at timestamptz NOT NULL DEFAULT now(), detected_by uuid, resolved_by uuid, resolved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.logistics_route_dispatch_links ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route_id uuid NOT NULL REFERENCES public.logistics_routes(id) ON DELETE CASCADE, stop_id uuid REFERENCES public.logistics_route_stops(id) ON DELETE SET NULL, dispatch_job_id uuid NOT NULL REFERENCES public.delivery_dispatch_jobs(id) ON DELETE CASCADE, linked_by uuid, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (route_id, dispatch_job_id) );
CREATE TABLE IF NOT EXISTS public.logistics_route_events ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), route_id uuid NOT NULL REFERENCES public.logistics_routes(id) ON DELETE CASCADE, stop_id uuid REFERENCES public.logistics_route_stops(id) ON DELETE SET NULL, route_version_id uuid REFERENCES public.logistics_route_versions(id) ON DELETE SET NULL, event_type text NOT NULL, from_status text, to_status text, reason text, actor_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ap360_exceptions ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version_id uuid REFERENCES public.ap360_versions(id) ON DELETE SET NULL, category_code text REFERENCES public.ap360_categories(code) ON DELETE SET NULL, kind text NOT NULL, status text NOT NULL DEFAULT 'pending', requested_price numeric(14,2), operator_floor numeric(14,2), market_reference numeric(14,2), variance_pct numeric(8,3), reason text NOT NULL, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, customer_impact text NOT NULL DEFAULT '', operator_impact text NOT NULL DEFAULT '', requested_by uuid, decided_by uuid, decided_at timestamptz, decision_note text, expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT ap360_exception_kind CHECK (kind IN ('below_floor','override_tolerance','market_outlier','negative_margin','floor_above_ceiling')), CONSTRAINT ap360_exception_status CHECK (status IN ('pending','approved','rejected','expired')) );
CREATE TABLE IF NOT EXISTS public.corporate_ride_approvals ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), corporate_id uuid NOT NULL REFERENCES public.corporate_accounts(id) ON DELETE CASCADE, employee_id uuid NOT NULL REFERENCES public.corporate_employees(id) ON DELETE CASCADE, department_id uuid REFERENCES public.corporate_departments(id) ON DELETE SET NULL, requested_by uuid NOT NULL, trip_request_id uuid, ride_type text, pickup_address text, dropoff_address text, estimated_fare_cents bigint NOT NULL, estimated_distance_km numeric, scheduled_for timestamptz, justification text, triggering_policy_id uuid REFERENCES public.corporate_ride_policies(id) ON DELETE SET NULL, triggering_rule_id uuid REFERENCES public.corporate_policy_rules(id) ON DELETE SET NULL, status public.corporate_approval_status NOT NULL DEFAULT 'pending', decided_by uuid, decided_at timestamptz, decision_note text, expires_at timestamptz NOT NULL DEFAULT (now() + interval '24 hours'), metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now() );
CREATE TABLE IF NOT EXISTS public.ap360_overrides ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version_id uuid NOT NULL REFERENCES public.ap360_versions(id) ON DELETE CASCADE, exception_id uuid REFERENCES public.ap360_exceptions(id) ON DELETE SET NULL, booking_ref text, operator_id uuid, original_price numeric(14,2) NOT NULL, requested_price numeric(14,2) NOT NULL, variance_pct numeric(8,3) NOT NULL, reason text NOT NULL, evidence jsonb NOT NULL DEFAULT '{}'::jsonb, approval_level text NOT NULL DEFAULT 'operator', approved_by uuid, approved_at timestamptz, expires_at timestamptz, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT ap360_override_prices CHECK (original_price >= 0 AND requested_price >= 0), CONSTRAINT ap360_override_level CHECK (approval_level IN ('operator','manager','super_admin')) );
ALTER TABLE public.air_pricing_settings ADD COLUMN IF NOT EXISTS fuel_surcharge_pct numeric NOT NULL DEFAULT 0.06, ADD COLUMN IF NOT EXISTS vat_pct numeric NOT NULL DEFAULT 0.16, ADD COLUMN IF NOT EXISTS vat_domestic_only boolean NOT NULL DEFAULT true;
ALTER TABLE public.charter_pricing_audit ADD COLUMN IF NOT EXISTS evidence_url TEXT, ADD COLUMN IF NOT EXISTS evidence_note TEXT;
ALTER TABLE public.commercial_quotations ADD COLUMN IF NOT EXISTS valid_from date, ADD COLUMN IF NOT EXISTS price_locked_until timestamptz;
ALTER TABLE public.delivery_route_segments ADD COLUMN IF NOT EXISTS route_id uuid REFERENCES public.logistics_routes(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS route_version_id uuid REFERENCES public.logistics_route_versions(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS stop_id uuid REFERENCES public.logistics_route_stops(id) ON DELETE SET NULL;
ALTER TABLE public.dispatch_surge_zones ADD COLUMN IF NOT EXISTS approval_status public.surge_approval_status NOT NULL DEFAULT 'PENDING', ADD COLUMN IF NOT EXISTS requested_by uuid, ADD COLUMN IF NOT EXISTS approved_by uuid, ADD COLUMN IF NOT EXISTS approved_at timestamptz, ADD COLUMN IF NOT EXISTS rejected_by uuid, ADD COLUMN IF NOT EXISTS rejected_at timestamptz, ADD COLUMN IF NOT EXISTS approval_notes text, ADD COLUMN IF NOT EXISTS priority integer NOT NULL DEFAULT 100;
ALTER TABLE public.dispatch_surge_zones ADD COLUMN IF NOT EXISTS first_approver_id uuid, ADD COLUMN IF NOT EXISTS first_approved_at timestamptz, ADD COLUMN IF NOT EXISTS first_approval_notes text, ADD COLUMN IF NOT EXISTS requires_two_approvals boolean NOT NULL DEFAULT false;
ALTER TABLE public.pricing_service_types ADD COLUMN IF NOT EXISTS engine_code text REFERENCES public.pricing_service_engines(code);
ALTER TABLE public.public_meeting_bookings ADD COLUMN IF NOT EXISTS meeting_type_id uuid, ADD COLUMN IF NOT EXISTS host_staff_id uuid REFERENCES public.staff_members(id), ADD COLUMN IF NOT EXISTS manage_token_hash text, ADD COLUMN IF NOT EXISTS lead_id uuid REFERENCES public.sales_leads(id), ADD COLUMN IF NOT EXISTS channel text NOT NULL DEFAULT 'client', ADD COLUMN IF NOT EXISTS booked_by uuid, ADD COLUMN IF NOT EXISTS outcome text CHECK (outcome IN ('held','no_show','follow_up','deal')), ADD COLUMN IF NOT EXISTS outcome_notes text, ADD COLUMN IF NOT EXISTS reminder_24h_at timestamptz, ADD COLUMN IF NOT EXISTS reminder_1h_at timestamptz, ADD COLUMN IF NOT EXISTS cancelled_reason text, ADD COLUMN IF NOT EXISTS rescheduled_from timestamptz;
ALTER TABLE public.public_meeting_bookings ADD COLUMN IF NOT EXISTS routing_reason text, ADD COLUMN IF NOT EXISTS availability_confidence text, ADD COLUMN IF NOT EXISTS lead_created boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS prep_work_item_id uuid REFERENCES public.staff_work_items(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS followup_work_item_id uuid REFERENCES public.staff_work_items(id) ON DELETE SET NULL;
ALTER TABLE public.public_meeting_bookings ADD COLUMN IF NOT EXISTS routing_explanation jsonb;
ALTER TABLE public.corporate_employees ADD COLUMN IF NOT EXISTS requires_approval boolean NOT NULL DEFAULT false;
ALTER TABLE public.dispatch_assignments ADD COLUMN IF NOT EXISTS metadata jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.corporate_policy_rules ADD COLUMN IF NOT EXISTS max_trips integer;
ALTER TABLE public.corporate_ride_approvals ADD COLUMN IF NOT EXISTS booking_id uuid REFERENCES public.trip_bookings(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS passenger_count integer NOT NULL DEFAULT 1, ADD COLUMN IF NOT EXISTS cost_center_code text, ADD COLUMN IF NOT EXISTS purpose text;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['air_pricing_settings','alert_dispatch_dlq','alert_escalation_routes','ap360_engines','ap360_families','approval_routes','asset_pricing_versions','charter_pricing_audit','charter_pricing_config','commercial_documents','commercial_pricing_requests','commercial_quotations','corporate_departments','country_pricing_floors','delivery_eta_predictions','delivery_route_segments','dispatch_acceptance_stats','dispatch_approval_audit','dispatch_approval_rate_limits','dispatch_demand_signals','dispatch_performance_metrics','dispatch_requests','dispatch_rules','dispatch_sim_scenarios','dispatch_supply_cells','dispatch_surge_zone_versions','dispatch_surge_zones','document_metadata','email_event_dispatch','fact_trips','fin_bank_receipts','freight_price_lineage','freight_repeat_routes','logistics_delivery_attempts','logistics_dispatch_events','logistics_hub_zones','logistics_match_runs','logistics_match_weights','logistics_route_optimization_runs','marketplace_dispatch_zones','marketplace_hex_cells','marketplace_pricing_rules','partner_lifecycle_dispatch_windows','pricing360_feature_flags','pricing360_role_grants','pricing_audit_events','pricing_guardrails','pricing_rule_sets','pricing_service_engines','pricing_service_types','public_meeting_bookings','rec_comm_dispatch_attempts','rename_alert_dispatch_log','rental_booking_events','ride_categories','ride_interventions','ride_receivables','rider_badges','rider_behavior_scores','rider_device_fingerprints','rider_fraud_signals','rider_locations','rider_points','rider_risk_profiles','rider_safety_incidents','rider_sos_alerts','rider_tiers','rider_trust_scores','trip_location_events','trip_share_access_log','trip_share_lockouts','trip_share_tokens','ap360_categories','asset_pricing_bands','asset_pricing_fee_components','city_pricing_rules','commercial_document_dispatches','corporate_employees','dispatch_assignments','dispatch_candidates','dispatch_engine_runs','dispatch_hex_assignments','dispatch_rule_versions','dispatch_sim_results','fin_reconciliation_matches','freight_route_commitments','freight_route_instances','logistics_exceptions','logistics_match_candidates','marketplace_eta_calibration','marketplace_surge_events','marketplace_surge_multipliers','meeting_booking_events','pricing_competitor_observations','pricing_components','pricing_cost_baselines','pricing_customer_rates','pricing_models','pricing_negotiations','pricing_quote_snapshots','rider_memberships','surge_rules','ap360_profiles','corporate_ride_policies','dispatch_eta_estimates','dispatch_events','dispatch_offer_timeouts','dispatch_rejections','dispatch_scores','freight_route_allocations','freight_route_exceptions','freight_route_manifests','logistics_route_stops','ap360_versions','corporate_policy_rules','freight_route_events','logistics_route_deviations','logistics_route_dispatch_links','logistics_route_events','ap360_exceptions','corporate_ride_approvals','ap360_overrides'] LOOP EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', t); EXECUTE format('GRANT ALL ON public.%I TO service_role', t); EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('CREATE POLICY "Admins manage restored records" ON public.%I FOR ALL TO authenticated USING (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'']::public.app_role[])) WITH CHECK (public.has_any_role(auth.uid(), ARRAY[''admin'',''super_admin'']::public.app_role[]))', t); END LOOP; END $$;
